CREATE TABLE `roles` (`id` UUID NOT NULL PRIMARY KEY, `name` VARCHAR(255) NOT NULL UNIQUE, `description` VARCHAR(255) NOT NULL, `permissions` TEXT NOT NULL DEFAULT '[]', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `users` (`id` UUID PRIMARY KEY, `email` VARCHAR(255) NOT NULL UNIQUE, `name` VARCHAR(255) NOT NULL, `username` VARCHAR(255) UNIQUE, `password` VARCHAR(255) NOT NULL, `is_approved` TINYINT(1) NOT NULL DEFAULT 0, `role_id` UUID REFERENCES `roles` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, `department` VARCHAR(255), `is_online` TINYINT(1) NOT NULL DEFAULT 0, `last_login` DATETIME, `created_at` DATETIME, `updated_at` DATETIME);
CREATE TABLE `monitoring_feeds` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `name` VARCHAR(255) NOT NULL, `is_online` TINYINT(1) NOT NULL, `stream_url` VARCHAR(255) NOT NULL, `location` VARCHAR(255), `ip_address` VARCHAR(255), `last_updated` DATETIME, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE `alerts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `title` VARCHAR(255) NOT NULL, `timestamp` DATETIME NOT NULL, `location` VARCHAR(255) NOT NULL, `type` VARCHAR(255) NOT NULL, `is_resolved` TINYINT(1) NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL);
CREATE TABLE `recordings` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `camera_id` INTEGER NOT NULL REFERENCES `monitoring_feeds` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE, `event_type` VARCHAR(255) NOT NULL, `file_path` VARCHAR(255) NOT NULL, `start_time` DATETIME NOT NULL, `end_time` DATETIME NOT NULL, `duration` VARCHAR(255) NOT NULL, `person_name` VARCHAR(255), `created_at` DATETIME NOT NULL);
